/**
 * Generates lib/shared/testIdAnchors.js, which maps CSAF test IDs (e.g. 6.1.2)
 * to the anchors of the corresponding chapters in the HTML versions of the
 * CSAF specification published by OASIS (e.g.
 * 612-multiple-definition-of-product-id).
 *
 * The anchors are generated by the OASIS toolchain from the heading text and
 * cannot be derived from the test ID alone. Run this script again when the
 * linked specification versions in lib/shared/testId.js change:
 *
 *   node scripts/generateTestIdAnchors.js
 */
import { writeFile } from 'node:fs/promises'

const SOURCES = {
  'v2.0': 'https://docs.oasis-open.org/csaf/csaf/v2.0/os/csaf-v2.0-os.html',
  'v2.1':
    'https://docs.oasis-open.org/csaf/csaf/v2.1/csd04/csaf-v2.1-csd04.html',
}

/**
 * Returns the anchors of all numbered headings of chapter 6 (tests). An
 * explicit `<a id>` inside of the heading is preferred over the id of the
 * heading itself, because it is chosen by the authors and unique.
 */
function anchors(/** @type {string} */ html) {
  /** @type {Record<string, string>} */
  const result = {}
  for (const heading of html.matchAll(/<h([2-6])([^>]*)>(.*?)<\/h\1>/gs)) {
    const number = heading[3].match(/^\s*(6(?:\.\d+)+)\s/)?.[1]
    if (!number) continue
    const anchor =
      heading[3].match(/<a id=['"]([^'"]+)['"]/)?.[1] ??
      heading[2].match(/\bid="([^"]+)"/)?.[1]
    if (anchor) result[number] = anchor
  }
  return result
}

/** @type {Record<string, Record<string, string>>} */
const all = {}
for (const [version, url] of Object.entries(SOURCES)) {
  const response = await fetch(url)
  if (!response.ok) throw new Error(`${url}: ${response.status}`)
  all[version] = anchors(await response.text())
}

await writeFile(
  new URL('../lib/shared/testIdAnchors.js', import.meta.url),
  `// Generated by scripts/generateTestIdAnchors.js, do not edit manually.\n\n` +
    `/** @type {Record<import('#lib/uiSchemas.js').UiSchemaVersion, Record<string, string>>} */\n` +
    `export default ${JSON.stringify(all, null, 2)}\n`,
)
